// Auto-generated ReadyPlayerMe Character Avatar GLB Base64 Data
window.AVATAR_GLB_DATA = "data:model/gltf-binary;base64,";


// Female Alias for explicit gender selection
window.AVATAR_FEMALE_GLB_DATA = window.AVATAR_GLB_DATA;

// Auto-generated ReadyPlayerMe Male Character Avatar GLB Base64 Data (Asfandyar)
window.AVATAR_MALE_GLB_DATA = "data:model/gltf-binary;base64,";


// ============================================================================
// 🛰️ 4-AVATAR CATALOG (2 BOYS / 2 GIRLS) & RANDOM PROBABILITY SYSTEM
// ============================================================================
window.AVATAR_PRESETS = {
  boy_1: {
    id: 'boy_1',
    gender: 'male',
    role: 'GSFC FLIGHT COMMANDER',
    defaultName: 'Alex (Commander)',
    modelType: 'male',
    modelUrl: '3D-assets/free-avatar-for-iclone/source/Asfandyar.glb',
    base64Key: 'AVATAR_MALE_GLB_DATA',
    accentColor: '#38bdf8', // Cyan / NASA Flight Blue
    badgeColor: '#38bdf8',
    suitTrimColor: 0x0284c7
  },
  boy_2: {
    id: 'boy_2',
    gender: 'male',
    role: 'GSFC PAYLOAD SPECIALIST',
    defaultName: 'Marcus (Specialist)',
    modelType: 'male',
    modelUrl: '3D-assets/free-avatar-for-iclone/source/Asfandyar.glb',
    base64Key: 'AVATAR_MALE_GLB_DATA',
    accentColor: '#f59e0b', // Solar Amber
    badgeColor: '#fbbf24',
    suitTrimColor: 0xf59e0b
  },
  girl_1: {
    id: 'girl_1',
    gender: 'female',
    role: 'GSFC SYSTEMS ENGINEER',
    defaultName: 'Nancy (Systems)',
    modelType: 'female',
    modelUrl: '3D-assets/nancy-wheeler/source/64de1345c603b299c004f2d6.glb',
    base64Key: 'AVATAR_GLB_DATA',
    accentColor: '#10b981', // Cleanroom Emerald
    badgeColor: '#34d399',
    suitTrimColor: 0x10b981
  },
  girl_2: {
    id: 'girl_2',
    gender: 'female',
    role: 'GSFC AVIONICS SPECIALIST',
    defaultName: 'Elena (Avionics)',
    modelType: 'female',
    modelUrl: '3D-assets/nancy-wheeler/source/64de1345c603b299c004f2d6.glb',
    base64Key: 'AVATAR_GLB_DATA',
    accentColor: '#a855f7', // Cosmic Violet
    badgeColor: '#c084fc',
    suitTrimColor: 0x8b5cf6
  }
};

window.AvatarSystem = {
  presets: window.AVATAR_PRESETS,

  // Equal 25% distribution across 4 characters (50% Male: boy_1, boy_2 / 50% Female: girl_1, girl_2)
  getRandomAvatarId() {
    const ids = ['boy_1', 'boy_2', 'girl_1', 'girl_2'];
    return ids[Math.floor(Math.random() * ids.length)];
  },

  // Dynamic probability balancing as players join (ensuring 2 boys & 2 girls crew)
  assignAvatarForPeer(existingAvatars = []) {
    let maleCount = 0;
    let femaleCount = 0;
    const usedIds = new Set(existingAvatars.filter(Boolean));

    existingAvatars.forEach(id => {
      const p = window.AVATAR_PRESETS[id];
      if (p) {
        if (p.gender === 'male') maleCount++;
        else if (p.gender === 'female') femaleCount++;
      }
    });

    const maleCandidates = ['boy_1', 'boy_2'].filter(id => !usedIds.has(id));
    const femaleCandidates = ['girl_1', 'girl_2'].filter(id => !usedIds.has(id));

    const poolMales = maleCandidates.length > 0 ? maleCandidates : ['boy_1', 'boy_2'];
    const poolFemales = femaleCandidates.length > 0 ? femaleCandidates : ['girl_1', 'girl_2'];

    let pickGender = 'male';
    if (maleCount > femaleCount) {
      // 80% probability for female when crew has more males
      pickGender = Math.random() < 0.8 ? 'female' : 'male';
    } else if (femaleCount > maleCount) {
      // 80% probability for male when crew has more females
      pickGender = Math.random() < 0.8 ? 'male' : 'female';
    } else {
      // 50-50 equal probability
      pickGender = Math.random() < 0.5 ? 'male' : 'female';
    }

    const pool = pickGender === 'male' ? poolMales : poolFemales;
    return pool[Math.floor(Math.random() * pool.length)];
  },

  getPreset(id) {
    if (id && window.AVATAR_PRESETS[id]) return window.AVATAR_PRESETS[id];
    return window.AVATAR_PRESETS.girl_1;
  },

  loadModelForPreset(preset, loader, onParsed, onError) {
    const parseBase64Data = (dataUri) => {
      try {
        if (!dataUri) return null;
        if (typeof window !== 'undefined') {
          if (!window.__CACHED_AVATAR_BUFFERS) window.__CACHED_AVATAR_BUFFERS = {};
          if (window.__CACHED_AVATAR_BUFFERS[dataUri]) {
            return window.__CACHED_AVATAR_BUFFERS[dataUri].slice(0);
          }
        }
        const base64Index = dataUri.indexOf('base64,');
        if (base64Index === -1) return null;
        const b64 = dataUri.substring(base64Index + 7);
        const binStr = window.atob(b64);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
        if (typeof window !== 'undefined') {
          window.__CACHED_AVATAR_BUFFERS[dataUri] = bytes.buffer;
        }
        return bytes.buffer.slice(0);
      } catch (e) {
        return null;
      }
    };

    if (preset.modelType === 'male') {
      if (typeof window !== 'undefined' && window.AVATAR_MALE_GLB_DATA) {
        const buf = parseBase64Data(window.AVATAR_MALE_GLB_DATA);
        if (buf) {
          loader.parse(buf, '', onParsed, onError);
          return;
        }
      }
      loader.load('3D-assets/free-avatar-for-iclone/source/Asfandyar.glb', onParsed, undefined, (err) => {
        console.warn('[AVATAR] Male URL load failed, fallback:', err);
        if (typeof window !== 'undefined' && window.AVATAR_GLB_DATA) {
          const buf = parseBase64Data(window.AVATAR_GLB_DATA);
          if (buf) loader.parse(buf, '', onParsed, onError);
        }
      });
      return;
    }

    // Female model
    if (typeof window !== 'undefined' && window.AVATAR_GLB_DATA) {
      const buf = parseBase64Data(window.AVATAR_GLB_DATA);
      if (buf) {
        loader.parse(buf, '', onParsed, onError);
        return;
      }
    }
    loader.load('3D-assets/nancy-wheeler/source/64de1345c603b299c004f2d6.glb', onParsed, undefined, onError);
  }
};
